As discussed in subsection \ref{sub.A}, the presence of exact symmetries--electric charge conservation, {\it CP}, and a global $Z_2$ symmetry--allows the full scattering amplitude matrix to be block-diagonalized into six independent sub-matrices. Each block corresponds to a distinct symmetry sector defined by quantum numbers of the initial and final states. These sectors and their associated sub-matrices are:\\
\textbf{Neutral {\it CP}-even and $Z_2$-even 8 by 8 matrix in the basis:} \{$h h$, $G^0 G^0$, $h_1 h_1$, $h_2 h_2$, $\omega_1 \omega_1$, $\omega_2 \omega_2$, $G^+ G^-$, $\phi^+ \phi^-$\}.
\begin{equation}
\left(
\begin{array}{cccccccc}
 6\lambda_1 & 2\lambda_1 & \kappa_1 + \kappa_2 + \kappa_3 & \kappa_4 & \kappa_1 + \kappa_2 - \kappa_3 & \kappa_4 & 2\lambda_1 & \kappa_1 \\
 2\lambda_1 & 6\lambda_1 & \kappa_1 + \kappa_2 - \kappa_3 & \kappa_4 & \kappa_1 + \kappa_2 + \kappa_3 & \kappa_4 & 2\lambda_1 & \kappa_1 \\
 \kappa_1 + \kappa_2 + \kappa_3 & \kappa_1 + \kappa_2 - \kappa_3 & 6\lambda_2 & \kappa_5 & 2\lambda_2 & \kappa_5 & \kappa_1 & 2\lambda_2 \\
 \kappa_4 & \kappa_4 & \kappa_5 & 6\lambda_3 & \kappa_5 & 2\lambda_3 & \kappa_4 & \kappa_5 \\
 \kappa_1 + \kappa_2 - \kappa_3 & \kappa_1 + \kappa_2 + \kappa_3 & 2\lambda_2 & \kappa_5 & 6\lambda_2 & \kappa_5 & \kappa_1 & 2\lambda_2 \\
 \kappa_4 & \kappa_4 & \kappa_5 & 2\lambda_3 & \kappa_5 & 6\lambda_3 & \kappa_4 & \kappa_5 \\
 2\lambda_1 & 2\lambda_1 & \kappa_1 & \kappa_4 & \kappa_1 & \kappa_4 & 4\lambda_1 & \kappa_1 + \kappa_2 \\
 \kappa_1 & \kappa_1 & 2\lambda_2 & \kappa_5 & 2\lambda_2 & \kappa_5 & \kappa_1 + \kappa_2 & 4\lambda_2
\end{array}
\right)
\end{equation}
\textbf{Neutral {\it CP}-even and $Z_2$-odd 5 by 5 matrix in the basis:} \{$h h_1$, $h h_2$, $G^0 \omega_1$, $G^0 \omega_2$, $G^+ \phi^-$\}.
\begin{equation}
\left(
\begin{array}{ccccc}
\kappa_1 & 0 & \kappa_3 & 0 & \frac{\kappa_1}{2} + \frac{\kappa_2}{2} \\
0 & \kappa_4 & 0 & 0 & 0 \\
\kappa_3 & 0 & \frac{\kappa_1}{4} + \frac{\kappa_2}{4} + \frac{\kappa_3}{4} & 0 & \frac{\kappa_2}{2} + \frac{\kappa_3}{2} \\
0 & 0 & 0 & \frac{\kappa_4}{2} & 0 \\
\frac{\kappa_2}{2} + \frac{\kappa_3}{2} & 0 & \frac{\kappa_2}{2} + \frac{\kappa_3}{2} & 0 & \frac{\kappa_3}{2}
\end{array}
\right)
\end{equation}
\textbf{Neutral {\it CP}-odd and $Z_2$-even 7 by 7 matrix in the basis:} \{$h G^0$, $h_1 \omega_1$, $h_1 \omega_2$, $h_2 \omega_1$, $h_2 \omega_2$, $G^+ G^-$, $\phi^+ \phi^-$\}.
\begin{equation}
\left(
\begin{array}{ccccccc}
2\lambda_1 & \kappa_3 & 0 & 0 & 0 & 0 & 0 \\
\kappa_3 & 2\lambda_2 & 0 & 0 & 0 & 0 & 0 \\
0 & 0 & \kappa_5 & 0 & 0 & 0 & 0 \\
0 & 0 & 0 & \kappa_5 & 0 & 0 & 0 \\
0 & 0 & 0 & 0 & 2\lambda_3 & 0 & 0 \\
0 & 0 & 0 & 0 & 0 & 4\lambda_1 & \kappa_1 + \kappa_2 \\
0 & 0 & 0 & \kappa_5 & 0 & \kappa_1 + \kappa_2 & 4\lambda_2
\end{array}
\right)    
\end{equation}
\textbf{Neutral {\it CP}-odd and $Z_2$-odd 5 by 5 matrix in the basis:} \{$h \omega_1$, $h \omega_2$, $G^0 h_1$, $G^0 h_2$, $G^+ \phi^-$\}.
\begin{equation}
\left(
\begin{array}{ccccc}
\kappa_1 + \kappa_2 - \kappa_3 & 0 & \kappa_3 & 0 & \frac{\kappa_2}{2} - \frac{\kappa_3}{2} \\
0 & \kappa_4 & 0 & 0 & 0 \\
\kappa_3 & 0 & \kappa_1 + \kappa_2 - \kappa_3 & 0 & -\frac{\kappa_2}{2} + \frac{\kappa_3}{2} \\
0 & 0 & 0 & \kappa_4 & 0 \\
\frac{\kappa_2}{2} - \frac{\kappa_3}{2} & 0 & -\frac{\kappa_2}{2} + \frac{\kappa_3}{2} & 0 & \frac{\kappa_3}{2}
\end{array}
\right)    
\end{equation}
\textbf{Charged and $Z_2$-even 6 by 6 matrix in the basis:} \{$h G^+$, $G^0 G^+$, $h_1 \phi^+$, $h_2 \phi^+$, $\omega_1 \phi^+$, $\omega_2 \phi^+$\}.
\begin{equation}
\left(
\begin{array}{cccccc}
2\lambda_1 & 0 & \frac{\kappa_2}{2} + \frac{\kappa_3}{2} & 0 & \frac{\kappa_2}{2} - \frac{\kappa_3}{2} & 0 \\
0 & 2\lambda_1 & -\frac{\kappa_2}{2} + \frac{\kappa_3}{2} & 0 & \frac{\kappa_2}{2} + \frac{\kappa_3}{2} & 0 \\
\frac{\kappa_2}{2} + \frac{\kappa_3}{2} & -\frac{\kappa_2}{2} + \frac{\kappa_3}{2} & 2\lambda_2 & 0 & 0 & 0 \\
0 & 0 & 0 & \kappa_5 & 0 & 0 \\
\frac{\kappa_2}{2} - \frac{\kappa_3}{2} & \frac{\kappa_2}{2} + \frac{\kappa_3}{2} & 0 & 0 & 2\lambda_2 & 0 \\
0 & 0 & 0 & 0 & 0 & \kappa_5
\end{array}
\right)      
\end{equation}
\textbf{Charged and $Z_2$-odd 6 by 6 matrix in the basis:} \{$h \phi^+$, $G^0 \phi^+$, $h_1 G^+$, $h_2 G^+$, $\omega_1 G^+$, $\omega_2 G^+$\}
\begin{equation}
\left(
\begin{array}{cccccc}
\kappa_1 & 0 & \frac{\kappa_2}{2} + \frac{\kappa_3}{2} & 0 & \frac{\kappa_2}{2} - \frac{\kappa_3}{2} & 0 \\
0 & \kappa_1 & -\frac{\kappa_2}{2} + \frac{\kappa_3}{2} & 0 & \frac{\kappa_2}{2} + \frac{\kappa_3}{2} & 0 \\
\frac{\kappa_2}{2} + \frac{\kappa_3}{2} & -\frac{\kappa_2}{2} + \frac{\kappa_3}{2} & \kappa_1 & 0 & 0 & 0 \\
0 & 0 & 0 & \kappa_4 & 0 & 0 \\
\frac{\kappa_2}{2} - \frac{\kappa_3}{2} & \frac{\kappa_2}{2} + \frac{\kappa_3}{2} & 0 & 0 & \kappa_1 & 0 \\
0 & 0 & 0 & 0 & 0 & \kappa_4
\end{array}
\right)      
\end{equation}
